const deadLetterExhaustedCommerceWebhookReceipts = `-- name: DeadLetterExhaustedCommerceWebhookReceipts :many
WITH terminal_clock AS MATERIALIZED (
    SELECT clock_timestamp()::timestamptz AS now_at
), candidates AS MATERIALIZED (
    SELECT receipts.id
    FROM commerce_webhook_receipts AS receipts
    WHERE (
        receipts.state IN ('received', 'failed')
        OR (
            receipts.state = 'processing'
            AND receipts.lease_expires_at <= (SELECT now_at FROM terminal_clock)
        )
    )
      AND (
          receipts.attempt_count >= 32
          OR receipts.created_at
              <= (SELECT now_at FROM terminal_clock) - interval '23 hours'
      )
    ORDER BY receipts.provider_created_at, receipts.id
    FOR UPDATE SKIP LOCKED
    LIMIT $1::int
)
UPDATE commerce_webhook_receipts AS receipts
SET state = 'dead_letter',
    lease_id = NULL,
    lease_expires_at = NULL,
    last_error_code = CASE
        WHEN receipts.attempt_count >= 32 THEN 'attempts_exhausted'
        ELSE 'receipt_expired'
    END,
    completed_at = COALESCE(receipts.completed_at, (SELECT now_at FROM terminal_clock)),
    updated_at = (SELECT now_at FROM terminal_clock),
    version = receipts.version + 1
FROM candidates
WHERE receipts.id = candidates.id
RETURNING receipts.id, receipts.company_id, receipts.environment, receipts.provider_event_id, receipts.provider_account_id, receipts.event_type, receipts.provider_object_id, receipts.payload_sha256, receipts.livemode, receipts.provider_created_at, receipts.state, receipts.lease_id, receipts.lease_expires_at, receipts.attempt_count, receipts.next_attempt_at, receipts.last_error_code, receipts.completed_at, receipts.created_at, receipts.updated_at, receipts.version
`

func (q *Queries) DeadLetterExhaustedCommerceWebhookReceipts(ctx context.Context, pageLimit int32) ([]CommerceWebhookReceipt, error) {
	rows, err := q.db.Query(ctx, deadLetterExhaustedCommerceWebhookReceipts, pageLimit)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []CommerceWebhookReceipt{}
	for rows.Next() {
		var i CommerceWebhookReceipt
		if err := rows.Scan(
			&i.ID,
			&i.CompanyID,
			&i.Environment,
			&i.ProviderEventID,
			&i.ProviderAccountID,
			&i.EventType,
			&i.ProviderObjectID,
			&i.PayloadSha256,
			&i.Livemode,
			&i.ProviderCreatedAt,
			&i.State,
			&i.LeaseID,
			&i.LeaseExpiresAt,
			&i.AttemptCount,
			&i.NextAttemptAt,
			&i.LastErrorCode,
			&i.CompletedAt,
			&i.CreatedAt,
			&i.UpdatedAt,
			&i.Version,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

