const pruneCommerceRateLimits = `-- name: PruneCommerceRateLimits :execrows
WITH stale AS (
    SELECT company_id, site_id, subject_hmac, action
    FROM commerce_rate_limits
    WHERE updated_at <= clock_timestamp()
        - $1::bigint * interval '1 millisecond'
      AND $1::bigint BETWEEN 2000 AND 7200000
    ORDER BY updated_at, company_id, site_id, action
    LIMIT 1000
    FOR UPDATE SKIP LOCKED
)
DELETE FROM commerce_rate_limits AS limits
USING stale
WHERE limits.company_id = stale.company_id
  AND limits.site_id = stale.site_id
  AND limits.subject_hmac = stale.subject_hmac
  AND limits.action = stale.action
`

func (q *Queries) PruneCommerceRateLimits(ctx context.Context, retentionMilliseconds int64) (int64, error) {
	result, err := q.db.Exec(ctx, pruneCommerceRateLimits, retentionMilliseconds)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

const pruneCommerceSiteChallenges = `-- name: PruneCommerceSiteChallenges :execrows
WITH stale AS (
    SELECT id
    FROM commerce_site_challenges
    WHERE expires_at <= $1::timestamptz
       OR consumed_at IS NOT NULL
    ORDER BY expires_at, id
    LIMIT 1000
    FOR UPDATE SKIP LOCKED
)
DELETE FROM commerce_site_challenges AS challenges
USING stale
WHERE challenges.id = stale.id
`

func (q *Queries) PruneCommerceSiteChallenges(ctx context.Context, now pgtype.Timestamptz) (int64, error) {
	result, err := q.db.Exec(ctx, pruneCommerceSiteChallenges, now)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

